-- =============================================================================================
-- ISTA Presensi — create all tables (MySQL 8.0+)                         schema version 2
-- =============================================================================================
-- Run once, as a user that may create tables in this app's database (e.g. root or the DBA):
--   mysql -u root -p ista_absen < 001_create_tables.sql
-- Run 000_create_database_and_user.sql first. Generated by backend/scripts/build-mysql-sql.mjs —
-- do not edit by hand. Later changes come as 002_*.sql, 003_*.sql, … run in order.
-- The app itself only needs SELECT/INSERT/UPDATE/DELETE on these tables.
-- Table names are case-sensitive on Linux: keep them exactly as written.
-- =============================================================================================

SET NAMES utf8mb4;

-- User: Staff accounts of this app. Teachers synced from the campus database have externalId set; name, nip, unit, email and active then come from there. passwordHash is empty until an admin issues a one-time password.
-- CreateTable
CREATE TABLE `User` (
    `id` VARCHAR(191) NOT NULL,
    `email` VARCHAR(191) NULL,
    `passwordHash` VARCHAR(191) NOT NULL,
    `name` VARCHAR(191) NOT NULL,
    `nip` VARCHAR(191) NOT NULL,
    `role` ENUM('USER', 'APPROVER', 'ADMIN') NOT NULL DEFAULT 'USER',
    `unit` VARCHAR(191) NOT NULL DEFAULT '',
    `annualQuota` INTEGER NOT NULL DEFAULT 12,
    `active` BOOLEAN NOT NULL DEFAULT true,
    `locale` ENUM('id', 'en') NOT NULL DEFAULT 'id',
    `theme` ENUM('light', 'dark') NOT NULL DEFAULT 'light',
    `mustChangePassword` BOOLEAN NOT NULL DEFAULT false,
    `sessionVersion` INTEGER NOT NULL DEFAULT 0,
    `externalId` VARCHAR(191) NULL,
    `lastSyncedAt` DATETIME(3) NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updatedAt` DATETIME(3) NOT NULL,

    UNIQUE INDEX `User_email_key`(`email`),
    UNIQUE INDEX `User_nip_key`(`nip`),
    UNIQUE INDEX `User_externalId_key`(`externalId`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- WorkSchedule: Which weekdays a person must be on campus, from effectiveFrom on (days = ISO weekdays, '24' = Tue+Thu). No row = Monday–Friday.
-- CreateTable
CREATE TABLE `WorkSchedule` (
    `id` VARCHAR(191) NOT NULL,
    `userId` VARCHAR(191) NOT NULL,
    `effectiveFrom` DATE NOT NULL,
    `days` VARCHAR(191) NOT NULL,
    `setById` VARCHAR(191) NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    UNIQUE INDEX `WorkSchedule_userId_effectiveFrom_key`(`userId`, `effectiveFrom`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- AttendanceExemption: Scheduled days an admin excused ("Bebaskan"): not absent, no leave deducted.
-- CreateTable
CREATE TABLE `AttendanceExemption` (
    `id` VARCHAR(191) NOT NULL,
    `userId` VARCHAR(191) NOT NULL,
    `date` DATE NOT NULL,
    `reason` TEXT NOT NULL,
    `createdById` VARCHAR(191) NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    INDEX `AttendanceExemption_date_idx`(`date`),
    UNIQUE INDEX `AttendanceExemption_userId_date_key`(`userId`, `date`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- AdminAction: Audit log of admin corrections: schedules, attendance added/edited/deleted, exemptions, issued passwords.
-- CreateTable
CREATE TABLE `AdminAction` (
    `id` VARCHAR(191) NOT NULL,
    `actorId` VARCHAR(191) NOT NULL,
    `targetUserId` VARCHAR(191) NOT NULL,
    `date` DATE NULL,
    `action` VARCHAR(191) NOT NULL,
    `reason` TEXT NULL,
    `details` JSON NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    INDEX `AdminAction_targetUserId_createdAt_idx`(`targetUserId`, `createdAt`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- UserPhoto: Profile pictures (JPEG bytes), one per user.
-- CreateTable
CREATE TABLE `UserPhoto` (
    `userId` VARCHAR(191) NOT NULL,
    `data` LONGBLOB NOT NULL,
    `mimeType` VARCHAR(191) NOT NULL,
    `size` INTEGER NOT NULL,
    `source` VARCHAR(191) NOT NULL DEFAULT 'UPLOAD',
    `sourceHash` VARCHAR(191) NULL,
    `updatedAt` DATETIME(3) NOT NULL,

    PRIMARY KEY (`userId`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Location: QR locations (kiosk screens). qrSecret signs the rotating codes; kioskKeyHash pairs one kiosk.
-- CreateTable
CREATE TABLE `Location` (
    `id` VARCHAR(191) NOT NULL,
    `name` VARCHAR(191) NOT NULL,
    `building` VARCHAR(191) NOT NULL DEFAULT '',
    `active` BOOLEAN NOT NULL DEFAULT true,
    `qrSecret` VARCHAR(191) NOT NULL,
    `kioskKeyHash` VARCHAR(191) NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updatedAt` DATETIME(3) NOT NULL,

    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Attendance: One row per person per day: clock-in/out times, locations, how the QR was read, fixes and admin edits.
-- CreateTable
CREATE TABLE `Attendance` (
    `id` VARCHAR(191) NOT NULL,
    `userId` VARCHAR(191) NOT NULL,
    `date` DATE NOT NULL,
    `clockIn` DATETIME(3) NOT NULL,
    `clockOut` DATETIME(3) NULL,
    `inLocationId` VARCHAR(191) NOT NULL,
    `outLocationId` VARCHAR(191) NULL,
    `status` ENUM('CLOCKED_IN', 'COMPLETE', 'MISSING_CLOCK_OUT', 'FIXED', 'DEDUCTED') NOT NULL DEFAULT 'CLOCKED_IN',
    `inMethod` ENUM('CAMERA', 'UPLOAD', 'MANUAL') NOT NULL DEFAULT 'CAMERA',
    `outMethod` ENUM('CAMERA', 'UPLOAD', 'MANUAL') NULL,
    `fixReason` TEXT NULL,
    `fixedAt` DATETIME(3) NULL,
    `deductedAt` DATETIME(3) NULL,
    `editedById` VARCHAR(191) NULL,
    `editedAt` DATETIME(3) NULL,
    `editReason` TEXT NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updatedAt` DATETIME(3) NOT NULL,

    INDEX `Attendance_date_idx`(`date`),
    INDEX `Attendance_status_idx`(`status`),
    UNIQUE INDEX `Attendance_userId_date_key`(`userId`, `date`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- LeaveRequest: Annual and sick leave requests and their approval.
-- CreateTable
CREATE TABLE `LeaveRequest` (
    `id` VARCHAR(191) NOT NULL,
    `type` ENUM('ANNUAL', 'SICK') NOT NULL DEFAULT 'ANNUAL',
    `userId` VARCHAR(191) NOT NULL,
    `startDate` DATE NOT NULL,
    `endDate` DATE NOT NULL,
    `days` INTEGER NOT NULL,
    `reason` TEXT NOT NULL,
    `status` ENUM('PENDING', 'APPROVED', 'REJECTED') NOT NULL DEFAULT 'PENDING',
    `decidedById` VARCHAR(191) NULL,
    `decidedAt` DATETIME(3) NULL,
    `decisionNote` TEXT NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updatedAt` DATETIME(3) NOT NULL,

    INDEX `LeaveRequest_userId_startDate_idx`(`userId`, `startDate`),
    INDEX `LeaveRequest_status_idx`(`status`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- LeaveAttachment: Doctor's notes for sick leave (JPEG or PDF bytes, max 5 MB).
-- CreateTable
CREATE TABLE `LeaveAttachment` (
    `requestId` VARCHAR(191) NOT NULL,
    `data` LONGBLOB NOT NULL,
    `mimeType` VARCHAR(191) NOT NULL,
    `fileName` VARCHAR(191) NOT NULL,
    `size` INTEGER NOT NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    PRIMARY KEY (`requestId`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Holiday: Public holidays and campus days off (not counted as leave days).
-- CreateTable
CREATE TABLE `Holiday` (
    `date` DATE NOT NULL,
    `name` VARCHAR(191) NOT NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    PRIMARY KEY (`date`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- SyncRun: Log of each teacher sync run (nightly or manual) and its results.
-- CreateTable
CREATE TABLE `SyncRun` (
    `id` VARCHAR(191) NOT NULL,
    `trigger` VARCHAR(191) NOT NULL,
    `actorId` VARCHAR(191) NULL,
    `startedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `finishedAt` DATETIME(3) NULL,
    `status` VARCHAR(191) NOT NULL,
    `sourceRows` INTEGER NOT NULL DEFAULT 0,
    `added` INTEGER NOT NULL DEFAULT 0,
    `updated` INTEGER NOT NULL DEFAULT 0,
    `deactivated` INTEGER NOT NULL DEFAULT 0,
    `reactivated` INTEGER NOT NULL DEFAULT 0,
    `skipped` INTEGER NOT NULL DEFAULT 0,
    `photos` INTEGER NOT NULL DEFAULT 0,
    `message` TEXT NULL,
    `problems` JSON NULL,

    INDEX `SyncRun_startedAt_idx`(`startedAt`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- SchemaVersion: Installed version of these scripts; the backend refuses to start if it is older than the code needs.
-- CreateTable
CREATE TABLE `SchemaVersion` (
    `version` INTEGER NOT NULL,
    `note` VARCHAR(191) NULL,
    `appliedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    PRIMARY KEY (`version`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

